    static String solve(String input) throws Exception {
        String[] lines=rows(input); Map<String,String[]> pages=new HashMap<>();
        for(int i=1;i<lines.length;i++){String[] f=lines[i].split("\\|",-1); pages.put(f[0],new String[]{f[1],f[2]});}
